36	/// This is used to store a QVideoFrame info while we are searching the image for QRCodes.
37	struct SimpleVideoFrame
38	{
39	    QByteArray data;
40	    QSize size;
41	    QVideoFrame::PixelFormat pixelFormat;
42	
43	    SimpleVideoFrame()
44	        : size{0,0}
45	        , pixelFormat{QVideoFrame::Format_Invalid}
46	    {}
47	
48	    void copyData(QVideoFrame & frame)
49	    {
50	        frame.map(QAbstractVideoBuffer::ReadOnly);
51	
52	        /// Copy video frame bytes to this.data
53	        /// This is made to try to get a better performance (less memory allocation, faster unmap)
54	        /// Any other task is performed in a QFuture task, as we want to leave the UI thread asap
55	        if(data.size() != frame.mappedBytes())
56	        {
57	            qDebug() << "needed to resize";
58	            qDebug() << "size: " << data.size() << ", new size: " << frame.mappedBytes();
59	            data.resize(frame.mappedBytes());
60	        }
61	        memcpy(data.data(), frame.bits(), frame.mappedBytes());
62	        size = frame.size();
63	        pixelFormat = frame.pixelFormat();
64	
65	        frame.unmap();
66	    }
67	};
