          "items": {
            "type": "object",
            "required": ["class", "loc"],
            "properties": {
              "class": {"type": "string",
                "enum": ["reuse_direct", "recompile_reuse", "needs_adaptation", "unadaptable"],
                "description": "闭轴：reuse_direct=直接复用（纯脚本/纯逻辑/标准库，跑已移植运行时零改动）；recompile_reuse=重编译复用（C/C++ 无平台 API，OHOS NDK 重编即可）；needs_adaptation=需适配（能用鸿蒙 API/自行实现重建、只是换方案：平台 API 调用点/平台分支/GUI 层重写/事件循环后端/x86-only asm 换 NEON 等）；unadaptable=无法适配（机制/硬件/闭源层无任何鸿蒙等价与回退：CUDA/专有 GPU、闭源二进制库、专有内核特性，模块须与 dim-9 unadaptable_apis 交叉引用）。判据：能否用鸿蒙可用 API 或自行实现重建功能？能→needs_adaptation，不能→unadaptable"},
              "loc": {"type": "integer", "description": "该桶生产代码行数（引用 dir_loc 机械数字之和）。字段名必须为 loc，不是 total_loc（面板/xlsx 只认 loc）"},
