247: QVariantMap QZXing::metadataToMap(const ResultMetadata &metadata)
248: {
249:     QVariantMap obj;
250:     for (const ResultMetadata::Key &key: metadata.keys()) {
251:         QString keyName = QString::fromStdString(metadata.keyToString(key));
252: 
253:         switch (key) {
254:         case ResultMetadata::ORIENTATION:
255:         case ResultMetadata::ISSUE_NUMBER:
256:         case ResultMetadata::STRUCTURED_APPEND_SEQUENCE:
257:         case ResultMetadata::STRUCTURED_APPEND_CODE_COUNT:
258:         case ResultMetadata::STRUCTURED_APPEND_PARITY:
259:             obj[keyName] = QVariant(metadata.getInt(key));
260:             break;
261:         case ResultMetadata::ERROR_CORRECTION_LEVEL:
262:         case ResultMetadata::SUGGESTED_PRICE:
263:         case ResultMetadata::POSSIBLE_COUNTRY:
264:         case ResultMetadata::UPC_EAN_EXTENSION:
265:             obj[keyName] = QVariant(metadata.getString(key).c_str());
266:             break;
267: 
268:         case ResultMetadata::OTHER:
269:         case ResultMetadata::PDF417_EXTRA_METADATA:
270:         case ResultMetadata::BYTE_SEGMENTS:
271:             break;
272:         }
273:     }
274: 
275:     return obj;
276: }
