            //        qDebug() << "saving image" << i << "at:" << path << frameToProcess.save(path);

            decoder.decodeImage(frameToProcess, frameToProcess.width(), frameToProcess.height());
        });
    }

#ifdef Q_OS_ANDROID
    f.unmap();
#endif
